import Foundation

/// Exercise names in other languages from wger.de (`exercise-names-i18n.json`, generated by `scripts/map-wger.mjs`;
/// only CC0 / CC-BY / CC-BY-SA names with a named author). Used for search and import matching; the app keeps showing
/// the English name, and lists these (with their credit) under "Other names" on the exercise detail screen.
struct ExerciseNamesI18n: Sendable {
    static let resourceName = "exercise-names-i18n"

    struct Name: Equatable, Sendable {
        let text: String
        let author: String
        let license: String
        /// wger also uses this name for another exercise: searchable, but never an automatic import match.
        var searchOnly = false
    }

    struct Language: Equatable, Sendable {
        /// ISO 639-1 code as wger gives it ("de", "es").
        let code: String
        let names: [Name]

        /// "German" for "de" in the device language; the code when unknown.
        var displayName: String { Locale.current.localizedString(forLanguageCode: code) ?? code }
    }

    struct Entry: Equatable, Sendable {
        /// Sorted by language code.
        let languages: [Language]
        /// The wger exercise pages the names come from (http/https only).
        let sources: [URL]

        /// Distinct authors and licenses, for the credit line.
        var authors: [String] { Self.unique(languages.flatMap { $0.names.map(\.author) }) }
        var licenses: [String] { Self.unique(languages.flatMap { $0.names.map(\.license) }) }

        private static func unique(_ values: [String]) -> [String] {
            values.reduce(into: [String]()) { if !$0.contains($1) { $0.append($1) } }
        }
    }

    private struct File: Decodable {
        struct Exercise: Decodable {
            let names: [String: [Item]]
            let sources: [String]?
        }
        struct Item: Decodable {
            let n: String
            let a: String
            let l: String
            let s: Bool?
        }
        let exercises: [String: Exercise]
    }

    private let entries: [String: Entry]

    init(data: Data) throws {
        let file = try JSONDecoder().decode(File.self, from: data)
        entries = file.exercises.compactMapValues { exercise in
            let languages = exercise.names.sorted { $0.key < $1.key }.compactMap { code, items -> Language? in
                let names = items.compactMap { item -> Name? in
                    let text = item.n.trimmingCharacters(in: .whitespacesAndNewlines)
                    let author = item.a.trimmingCharacters(in: .whitespacesAndNewlines)
                    guard !text.isEmpty, !author.isEmpty, !item.l.isEmpty else { return nil }
                    return Name(text: text, author: author, license: item.l, searchOnly: item.s == true)
                }
                return names.isEmpty ? nil : Language(code: code, names: names)
            }
            guard !languages.isEmpty else { return nil }
            let sources = (exercise.sources ?? []).compactMap { PhotoCredit.webURL(URL(string: $0)) }
            return Entry(languages: languages, sources: sources)
        }
    }

    /// The bundled names, or nil when the resource is missing or unreadable (search then uses English names only).
    static func bundled(_ bundle: Bundle = .main) -> ExerciseNamesI18n? {
        guard let url = bundle.url(forResource: resourceName, withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        do { return try ExerciseNamesI18n(data: data) } catch {
            MediaLog.log.error("Other-language names unreadable: \(error.localizedDescription, privacy: .public)")
            return nil
        }
    }

    func entry(for id: String) -> Entry? { entries[id] }

    /// All other-language names of an exercise, languages in code order.
    func names(for id: String) -> [String] {
        entries[id]?.languages.flatMap { $0.names.map(\.text) } ?? []
    }

    /// Library id -> names, for `ExerciseLibrary(exercises:otherNames:importNames:)`.
    var searchNames: [String: [String]] { entries.mapValues { $0.languages.flatMap { $0.names.map(\.text) } } }

    /// Library id -> names that may resolve imports automatically (search-only names left out).
    var importNames: [String: [String]] {
        entries.mapValues { $0.languages.flatMap { $0.names.filter { !$0.searchOnly }.map(\.text) } }
            .filter { !$0.value.isEmpty }
    }
}
